use CloudPDF\CloudPDFClient;

$client = new CloudPDFClient(
    token: '<token>',
);

$client->doc->annotations->reorder(
    'docId',
    'layerName',
    'pageKey',
    new DocAnnotationsReorderRequest([
        'refs' => [
            AnnotationRef::objectNumber(new AnnotationRefObjectNumber([
                'page' => new PageRef([
                    'kind' => PageRefKind::ObjectNumber->value,
                    'objectNumber' => 1,
                ]),
                'objectNumber' => 1,
            ])),
        ],
        'position' => AnnotationPositionZero::Start->value,
    ]),
);

csharp.source:
using CloudPDF;

var client = new CloudPDFClient(
    "<token>"
);

await client.Doc.Annotations.ReorderAsync(
    new DocAnnotationsReorderRequest
    {
        DocId = "docId",
        LayerName = "layerName",
        PageKey = "pageKey",
        Refs = new List<AnnotationRef>()
        {
            new AnnotationRef(
                new AnnotationRef.ObjectNumber(
                    new AnnotationRefObjectNumber
                    {
                        Page = new PageRef { Kind = PageRefKind.ObjectNumber, ObjectNumber = 1 },
                        ObjectNumber = 1,
                    }
                )
            ),
        },
        Position = AnnotationPositionZero.Start,
    }
);

go.source:
import (
    "context"

    cloudpdf "github.com/embedpdf/cloudpdf-sdk-go/v3"
    client "github.com/embedpdf/cloudpdf-sdk-go/v3/client"
    option "github.com/embedpdf/cloudpdf-sdk-go/v3/option"
)

client := client.NewClient(
    option.WithToken("<token>"),
)

request := &doc.DocAnnotationsReorderRequest{
    DocID: "docId",
    LayerName: "layerName",
    PageKey: "pageKey",
    Refs: []*cloudpdf.AnnotationRef{
        &cloudpdf.AnnotationRef{
            ObjectNumber: &cloudpdf.AnnotationRefObjectNumber{
                Page: &cloudpdf.PageRef{
                    Kind: cloudpdf.PageRefKindObjectNumber,
                    ObjectNumber: 1,
                },
                ObjectNumber: 1,
            },
        },
    },
    Position: &cloudpdf.AnnotationPosition{
        AnnotationPositionZero: cloudpdf.AnnotationPositionZeroStart,
    },
}
client.Doc.Annotations.Reorder(
    context.TODO(),
    request,
)

